'use client';

import * as React from 'react';
import './icon-button.css';

/* ICON BUTTON: a pressable cap with only a glyph.
 *   tool    a graphite cap (38, radius 15); pressed sinks 1 into a dark well; latched (pressed={true})
 *           stays down with a 4 pt green LED top right
 *   ghost   a flat round button (28) that fills on hover
 *   mini    a small flat pill (18 × 16) inside a chip; `accept` greens its glyph on hover
 * It renders a <button>; pass `render` through Base UI parts (Toolbar.Button) to join their focus. */

export interface IconButtonProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  variant?: 'tool' | 'ghost' | 'mini';
  /** The accessible name (and the tooltip, when the host adds one). */
  label: string;
  icon: React.ReactNode;
  /** Latched: the tool stays pressed with its LED. Omit for a momentary button. */
  pressed?: boolean;
  /** mini: an accept action (✓), green on hover. */
  accept?: boolean;
}

export const IconButton = React.forwardRef<HTMLButtonElement, IconButtonProps>(function IconButton(
  { variant = 'ghost', label, icon, pressed, accept, className, type = 'button', ...props },
  ref,
) {
  return (
    <button
      ref={ref}
      type={type}
      aria-label={label}
      aria-pressed={pressed === undefined ? undefined : pressed}
      data-variant={variant}
      data-pressed={pressed ? '' : undefined}
      data-accept={accept ? '' : undefined}
      className={className ? `mu-icon-button mu-icon-trigger ${className}` : 'mu-icon-button mu-icon-trigger'}
      {...props}
    >
      {icon}
    </button>
  );
});

@import "../tokens.css";

/* Icon button: a pressable cap with only a glyph. Its look is the icon-button recipe (--mu-r-icon-button-*). */
.mu-icon-button {
  position: relative;
  box-sizing: border-box;
  display: inline-grid;
  place-items: center;
  flex: none;
  padding: var(--mu-zero);
  border: var(--mu-zero);
  background: transparent;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.mu-icon-button:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-zero); }
.mu-icon-button:disabled { opacity: var(--mu-r-button-self-disabled); cursor: default; }

/* tool: the graphite cap */
.mu-icon-button[data-variant="tool"] {
  width: var(--mu-r-icon-button-tool-size);
  height: var(--mu-r-icon-button-tool-size);
  border-radius: var(--mu-r-icon-button-tool-radius);
  color: var(--mu-r-icon-button-tool-ink);
  background: var(--mu-r-icon-button-tool-background);
  box-shadow: var(--mu-r-icon-button-tool-shadow);
  transition: transform var(--mu-r-icon-button-tool-press-time) linear, box-shadow var(--mu-r-icon-button-tool-shadow-time) var(--mu-ease-press);
}
.mu-icon-button[data-variant="tool"] > svg { width: var(--mu-r-icon-button-tool-glyph); height: var(--mu-r-icon-button-tool-glyph); }
.mu-icon-button[data-variant="tool"]:is(:active, [data-pressed]) {
  transform: translateY(var(--mu-r-icon-button-tool-press));
  background: var(--mu-r-icon-button-tool-pressed-background);
  box-shadow: var(--mu-r-icon-button-tool-pressed-shadow);
}
.mu-icon-button[data-variant="tool"][data-pressed]::after {
  content: "";
  position: absolute;
  top: var(--mu-r-icon-button-led-inset);
  right: var(--mu-r-icon-button-led-inset);
  width: var(--mu-r-icon-button-led-size);
  height: var(--mu-r-icon-button-led-size);
  border-radius: var(--mu-round);
  background: var(--mu-r-icon-button-led-background);
  box-shadow: var(--mu-r-icon-button-led-shadow);
}

/* ghost: flat, round, fills on hover */
.mu-icon-button[data-variant="ghost"] {
  width: var(--mu-r-icon-button-ghost-size);
  height: var(--mu-r-icon-button-ghost-size);
  border-radius: var(--mu-radius-pill);
  color: var(--mu-r-icon-button-ghost-ink);
  transition: background var(--mu-r-icon-button-self-fade), color var(--mu-r-icon-button-self-fade);
}
.mu-icon-button[data-variant="ghost"] > svg { width: var(--mu-r-icon-button-ghost-glyph); height: var(--mu-r-icon-button-ghost-glyph); }
.mu-icon-button[data-variant="ghost"]:hover { background: var(--mu-r-icon-button-ghost-hover-background); color: var(--mu-r-icon-button-ghost-ink-hover); }

/* mini: a small pill inside a chip */
.mu-icon-button[data-variant="mini"] {
  width: var(--mu-r-icon-button-mini-w);
  height: var(--mu-r-icon-button-mini-h);
  border-radius: var(--mu-radius-pill);
  font: var(--mu-r-icon-button-mini-font);
  color: var(--mu-r-icon-button-mini-ink);
  transition: background var(--mu-r-icon-button-self-fade), color var(--mu-r-icon-button-self-fade);
}
.mu-icon-button[data-variant="mini"]:hover { background: var(--mu-r-icon-button-mini-hover-background); color: var(--mu-r-icon-button-mini-ink-hover); }
.mu-icon-button[data-variant="mini"][data-accept]:hover { color: var(--mu-r-icon-button-mini-accept-ink); }
